// 1. Define strict types for status and priority
export type TaskStatus = 'Todo' | 'In Progress' | 'Under Review' | 'Completed';
export type TaskPriority = 'Low' | 'Medium' | 'High' | 'Critical';

// 2. Main Task Interface
export interface ITask {
  // System Metadata (Auto-generated by Backend/DB)
  id: number | string;            // Use string if you use UUIDs instead of auto-incrementing numbers
  createdAt: Date | string;       // ISO string from API or native Date object
  updatedAt: Date | string;

  // Core Task Information (User Inputs)
  title: string;
  description: string;
  dueDate: Date | string | null;  // Nullable if tasks don't require deadlines

  // Status & Organization
  status: TaskStatus;
  priority: TaskPriority;
  tags: string[];                 // Array of categories like ['Backend', 'Bug']

  // Relationships & Ownership (Foreign Keys)
  createdBy: number | string;     // ID of the user who made the task
  assignedTo: number | string | null; // Nullable if the task is unassigned
  projectId?: number | string;    // Optional field if tasks belong to a project
}

// 3. Helper Interface for creating a new task (omits auto-generated fields)
export interface ICreateTaskInput extends Omit<ITask, 'id' | 'createdAt' | 'updatedAt'> {}
